  final SyncStatus syncStatus;
  final bool isActive;
  final DateTime? updatedAt;
  const Product({
    required this.id,
    required this.sku,
    required this.name,
    this.categoryId,
    this.speciesId,
    required this.unit,
    required this.pricingMode,
    this.priceMin,
    this.priceMax,
    required this.tvaRate,
    required this.stockQty,
