    map['unit'] = Variable<String>(unit);
    map['pricing_mode'] = Variable<String>(pricingMode);
    if (!nullToAbsent || priceMin != null) {
      map['price_min'] = Variable<double>(priceMin);
    }
    if (!nullToAbsent || priceMax != null) {
      map['price_max'] = Variable<double>(priceMax);
    }
    map['tva_rate'] = Variable<double>(tvaRate);
    map['stock_qty'] = Variable<double>(stockQty);
    if (!nullToAbsent || alertThreshold != null) {
      map['alert_threshold'] = Variable<double>(alertThreshold);
    }
    if (!nullToAbsent || description != null) {
      map['description'] = Variable<String>(description);
    }
    {
      map['sync_status'] = Variable<String>(
        $ProductsTable.$convertersyncStatus.toSql(syncStatus),
      );
    }
    map['is_active'] = Variable<bool>(isActive);
    if (!nullToAbsent || updatedAt != null) {
      map['updated_at'] = Variable<DateTime>(updatedAt);
    }
    return map;
  }

  ProductsCompanion toCompanion(bool nullToAbsent) {
    return ProductsCompanion(
      id: Value(id),
      sku: Value(sku),
      name: Value(name),
      categoryId: categoryId == null && nullToAbsent
