class Customer extends DataClass implements Insertable<Customer> {
  final String id;
  final String name;
  final String? phone;
  final String? city;

  /// Adresse e-mail (ticket F0.72) : le tirage la sert désormais, le formulaire la saisit.
  final String? email;

  /// Plafond de crédit accordé, en FCFA. ⚠️ Jamais saisi ni envoyé par le poste.
  final double creditLimit;
  final bool isActive;

  /// ⚠️ **UNE FICHE CRÉÉE, MODIFIÉE OU ARCHIVÉE AU POSTE EST `pending` JUSQU'À
  /// L'ACQUITTEMENT** (ticket F0.72). Défaut `synced` : tout ce qui descend du serveur
  /// l'est, et les lignes d'avant la migration aussi. Le tirage ne touche JAMAIS une
  /// fiche qui ne l'est pas.
  final SyncStatus syncStatus;
  const Customer({
    required this.id,
    required this.name,
    this.phone,
    this.city,
    this.email,
    required this.creditLimit,
    required this.isActive,
    required this.syncStatus,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<String>(id);
    map['name'] = Variable<String>(name);
    if (!nullToAbsent || phone != null) {
      map['phone'] = Variable<String>(phone);
    }
    if (!nullToAbsent || city != null) {
      map['city'] = Variable<String>(city);
    }
    if (!nullToAbsent || email != null) {
      map['email'] = Variable<String>(email);
    }
    map['credit_limit'] = Variable<double>(creditLimit);
    map['is_active'] = Variable<bool>(isActive);
    {
      map['sync_status'] = Variable<String>(
        $CustomersTable.$convertersyncStatus.toSql(syncStatus),
      );
    }
    return map;
  }

  CustomersCompanion toCompanion(bool nullToAbsent) {
    return CustomersCompanion(
      id: Value(id),
      name: Value(name),
      phone: phone == null && nullToAbsent
          ? const Value.absent()
          : Value(phone),
      city: city == null && nullToAbsent ? const Value.absent() : Value(city),
      email: email == null && nullToAbsent
          ? const Value.absent()
          : Value(email),
      creditLimit: Value(creditLimit),
      isActive: Value(isActive),
      syncStatus: Value(syncStatus),
    );
  }

  factory Customer.fromJson(
    Map<String, dynamic> json, {
    ValueSerializer? serializer,
  }) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return Customer(
      id: serializer.fromJson<String>(json['id']),
      name: serializer.fromJson<String>(json['name']),
      phone: serializer.fromJson<String?>(json['phone']),
      city: serializer.fromJson<String?>(json['city']),
      email: serializer.fromJson<String?>(json['email']),
      creditLimit: serializer.fromJson<double>(json['creditLimit']),
      isActive: serializer.fromJson<bool>(json['isActive']),
      syncStatus: $CustomersTable.$convertersyncStatus.fromJson(
        serializer.fromJson<String>(json['syncStatus']),
      ),
    );
  }
  @override
  Map<String, dynamic> toJson({ValueSerializer? serializer}) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return <String, dynamic>{
      'id': serializer.toJson<String>(id),
      'name': serializer.toJson<String>(name),
      'phone': serializer.toJson<String?>(phone),
      'city': serializer.toJson<String?>(city),
      'email': serializer.toJson<String?>(email),
      'creditLimit': serializer.toJson<double>(creditLimit),
      'isActive': serializer.toJson<bool>(isActive),
      'syncStatus': serializer.toJson<String>(
        $CustomersTable.$convertersyncStatus.toJson(syncStatus),
      ),
    };
  }

  Customer copyWith({
    String? id,
    String? name,
    Value<String?> phone = const Value.absent(),
    Value<String?> city = const Value.absent(),
    Value<String?> email = const Value.absent(),
    double? creditLimit,
    bool? isActive,
    SyncStatus? syncStatus,
  }) => Customer(
    id: id ?? this.id,
    name: name ?? this.name,
    phone: phone.present ? phone.value : this.phone,
    city: city.present ? city.value : this.city,
    email: email.present ? email.value : this.email,
    creditLimit: creditLimit ?? this.creditLimit,
    isActive: isActive ?? this.isActive,
    syncStatus: syncStatus ?? this.syncStatus,
  );
  Customer copyWithCompanion(CustomersCompanion data) {
    return Customer(
      id: data.id.present ? data.id.value : this.id,
      name: data.name.present ? data.name.value : this.name,
      phone: data.phone.present ? data.phone.value : this.phone,
      city: data.city.present ? data.city.value : this.city,
      email: data.email.present ? data.email.value : this.email,
      creditLimit: data.creditLimit.present
          ? data.creditLimit.value
          : this.creditLimit,
      isActive: data.isActive.present ? data.isActive.value : this.isActive,
      syncStatus: data.syncStatus.present
          ? data.syncStatus.value
          : this.syncStatus,
    );
  }

  @override
  String toString() {
    return (StringBuffer('Customer(')
          ..write('id: $id, ')
          ..write('name: $name, ')
          ..write('phone: $phone, ')
          ..write('city: $city, ')
          ..write('email: $email, ')
          ..write('creditLimit: $creditLimit, ')
          ..write('isActive: $isActive, ')
          ..write('syncStatus: $syncStatus')
          ..write(')'))
        .toString();
  }

  @override
  int get hashCode => Object.hash(
    id,
    name,
    phone,
    city,
    email,
    creditLimit,
    isActive,
    syncStatus,
  );
  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      (other is Customer &&
          other.id == this.id &&
          other.name == this.name &&
          other.phone == this.phone &&
          other.city == this.city &&
          other.email == this.email &&
          other.creditLimit == this.creditLimit &&
          other.isActive == this.isActive &&
          other.syncStatus == this.syncStatus);
}

