class Sujet extends DataClass implements Insertable<Sujet> {
  final String id;
  final String identifier;
  final String? speciesLabel;
  final String? lotId;
  final String? lotCode;
  final String category;

  /// `F` ou `M`.
  final String sex;
  final String? breed;
  final DateTime? birthDate;
  final DateTime? entryDate;
  final String? origin;
  final String? cage;

  /// `actif`, `vendu`, `mort`, `reforme`…
  final String status;
  final DateTime? exitDate;
  final String? exitReason;
  final bool isActive;

  /// Ticket BS3 (v51) — l'identifiant de l'ESPÈCE du sujet (le serveur le sert depuis BS3) : le poste écrit désormais un
  /// sujet nominatif et l'envoie avec `species_id`. `null` : sujet reçu d'un serveur antérieur.
  final String? speciesId;

  /// ⚠️ **UN SUJET ENREGISTRÉ, MODIFIÉ OU SORTI AU POSTE EST `pending` JUSQU'À L'ACQUITTEMENT** (ticket BS3, v51). Défaut
  /// `synced` : tout ce qui descend du serveur l'est. Le tirage ne touche JAMAIS un sujet qui ne l'est pas
  /// (`_absorberSujets`).
  final SyncStatus syncStatus;

  /// Ticket BS3 (v51) — instant de la dernière saisie au poste : l'accusé de réception n'acquitte que la VERSION partie.
  final DateTime? updatedAt;
  const Sujet({
    required this.id,
    required this.identifier,
    this.speciesLabel,
    this.lotId,
    this.lotCode,
    required this.category,
    required this.sex,
    this.breed,
    this.birthDate,
    this.entryDate,
    this.origin,
    this.cage,
    required this.status,
    this.exitDate,
    this.exitReason,
    required this.isActive,
    this.speciesId,
    required this.syncStatus,
    this.updatedAt,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<String>(id);
    map['identifier'] = Variable<String>(identifier);
    if (!nullToAbsent || speciesLabel != null) {
      map['species_label'] = Variable<String>(speciesLabel);
    }
    if (!nullToAbsent || lotId != null) {
      map['lot_id'] = Variable<String>(lotId);
    }
    if (!nullToAbsent || lotCode != null) {
      map['lot_code'] = Variable<String>(lotCode);
    }
    map['category'] = Variable<String>(category);
    map['sex'] = Variable<String>(sex);
    if (!nullToAbsent || breed != null) {
      map['breed'] = Variable<String>(breed);
    }
    if (!nullToAbsent || birthDate != null) {
      map['birth_date'] = Variable<DateTime>(birthDate);
    }
    if (!nullToAbsent || entryDate != null) {
      map['entry_date'] = Variable<DateTime>(entryDate);
    }
    if (!nullToAbsent || origin != null) {
      map['origin'] = Variable<String>(origin);
    }
    if (!nullToAbsent || cage != null) {
      map['cage'] = Variable<String>(cage);
