class Purchase extends DataClass implements Insertable<Purchase> {
  final String id;
  final String deviceId;
  final SyncStatus syncStatus;
  final DateTime updatedAt;
  final String supplierId;

  /// Nom et catégorie servis avec l'achat : le poste doit afficher la liste
  /// même si le fournisseur a été archivé depuis.
  final String? supplierName;
  final String? supplierCategory;
  final String paymentMode;
  final String? treasuryAccountId;
  final double total;
  final double amountPaid;

  /// ⚠️ Calculé par le SERVEUR pour les achats reçus, jamais au poste : deux
  /// règles de statut donneraient deux listes pour la même ferme.
  final bool hasDebt;
  final DateTime purchaseDate;

  /// Instant où le SERVEUR a retourné l'achat (`returned_at`), nul sinon (ticket F0.74).
  /// ⚠️ Jamais écrit au poste : il vient du tirage. Un retour demandé ici mais pas encore
  /// appliqué vit dans `purchase_returns`.
  final DateTime? returnedAt;

  /// Part déjà payée devenue créance sur le fournisseur (`supplier_credit`, compte 409).
  /// Nulle tant que le serveur ne l'a pas servie : le poste ne la calcule pas.
  final double? supplierCredit;
  const Purchase({
    required this.id,
    required this.deviceId,
    required this.syncStatus,
    required this.updatedAt,
    required this.supplierId,
    this.supplierName,
    this.supplierCategory,
    required this.paymentMode,
    this.treasuryAccountId,
    required this.total,
    required this.amountPaid,
    required this.hasDebt,
    required this.purchaseDate,
    this.returnedAt,
    this.supplierCredit,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<String>(id);
    map['device_id'] = Variable<String>(deviceId);
    {
      map['sync_status'] = Variable<String>(
        $PurchasesTable.$convertersyncStatus.toSql(syncStatus),
      );
    }
    map['updated_at'] = Variable<DateTime>(updatedAt);
    map['supplier_id'] = Variable<String>(supplierId);
    if (!nullToAbsent || supplierName != null) {
      map['supplier_name'] = Variable<String>(supplierName);
    }
    if (!nullToAbsent || supplierCategory != null) {
      map['supplier_category'] = Variable<String>(supplierCategory);
    }
    map['payment_mode'] = Variable<String>(paymentMode);
    if (!nullToAbsent || treasuryAccountId != null) {
      map['treasury_account_id'] = Variable<String>(treasuryAccountId);
    }
    map['total'] = Variable<double>(total);
    map['amount_paid'] = Variable<double>(amountPaid);
    map['has_debt'] = Variable<bool>(hasDebt);
    map['purchase_date'] = Variable<DateTime>(purchaseDate);
    if (!nullToAbsent || returnedAt != null) {
      map['returned_at'] = Variable<DateTime>(returnedAt);
    }
    if (!nullToAbsent || supplierCredit != null) {
      map['supplier_credit'] = Variable<double>(supplierCredit);
    }
    return map;
  }

  PurchasesCompanion toCompanion(bool nullToAbsent) {
    return PurchasesCompanion(
      id: Value(id),
      deviceId: Value(deviceId),
      syncStatus: Value(syncStatus),
      updatedAt: Value(updatedAt),
      supplierId: Value(supplierId),
      supplierName: supplierName == null && nullToAbsent
          ? const Value.absent()
          : Value(supplierName),
      supplierCategory: supplierCategory == null && nullToAbsent
          ? const Value.absent()
          : Value(supplierCategory),
      paymentMode: Value(paymentMode),
      treasuryAccountId: treasuryAccountId == null && nullToAbsent
          ? const Value.absent()
          : Value(treasuryAccountId),
      total: Value(total),
      amountPaid: Value(amountPaid),
      hasDebt: Value(hasDebt),
      purchaseDate: Value(purchaseDate),
      returnedAt: returnedAt == null && nullToAbsent
          ? const Value.absent()
          : Value(returnedAt),
      supplierCredit: supplierCredit == null && nullToAbsent
          ? const Value.absent()
          : Value(supplierCredit),
    );
  }

  factory Purchase.fromJson(
    Map<String, dynamic> json, {
    ValueSerializer? serializer,
  }) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return Purchase(
      id: serializer.fromJson<String>(json['id']),
      deviceId: serializer.fromJson<String>(json['deviceId']),
      syncStatus: $PurchasesTable.$convertersyncStatus.fromJson(
        serializer.fromJson<String>(json['syncStatus']),
      ),
      updatedAt: serializer.fromJson<DateTime>(json['updatedAt']),
      supplierId: serializer.fromJson<String>(json['supplierId']),
      supplierName: serializer.fromJson<String?>(json['supplierName']),
      supplierCategory: serializer.fromJson<String?>(json['supplierCategory']),
      paymentMode: serializer.fromJson<String>(json['paymentMode']),
      treasuryAccountId: serializer.fromJson<String?>(
        json['treasuryAccountId'],
      ),
      total: serializer.fromJson<double>(json['total']),
      amountPaid: serializer.fromJson<double>(json['amountPaid']),
      hasDebt: serializer.fromJson<bool>(json['hasDebt']),
      purchaseDate: serializer.fromJson<DateTime>(json['purchaseDate']),
      returnedAt: serializer.fromJson<DateTime?>(json['returnedAt']),
      supplierCredit: serializer.fromJson<double?>(json['supplierCredit']),
    );
  }
  @override
  Map<String, dynamic> toJson({ValueSerializer? serializer}) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return <String, dynamic>{
      'id': serializer.toJson<String>(id),
      'deviceId': serializer.toJson<String>(deviceId),
      'syncStatus': serializer.toJson<String>(
        $PurchasesTable.$convertersyncStatus.toJson(syncStatus),
      ),
      'updatedAt': serializer.toJson<DateTime>(updatedAt),
      'supplierId': serializer.toJson<String>(supplierId),
      'supplierName': serializer.toJson<String?>(supplierName),
