  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<String>(id);
    map['device_id'] = Variable<String>(deviceId);
    {
      map['sync_status'] = Variable<String>(
        $SalesTable.$convertersyncStatus.toSql(syncStatus),
      );
    }
    map['updated_at'] = Variable<DateTime>(updatedAt);
    if (!nullToAbsent || customerId != null) {
      map['customer_id'] = Variable<String>(customerId);
    }
    map['payment_mode'] = Variable<String>(paymentMode);
    map['subtotal'] = Variable<double>(subtotal);
    map['discount'] = Variable<double>(discount);
    map['total'] = Variable<double>(total);
    if (!nullToAbsent || cashReceived != null) {
      map['cash_received'] = Variable<double>(cashReceived);
    }
    if (!nullToAbsent || changeDue != null) {
      map['change_due'] = Variable<double>(changeDue);
    }
    map['status'] = Variable<String>(status);
    map['sold_at'] = Variable<DateTime>(soldAt);
    if (!nullToAbsent || customerName != null) {
      map['customer_name'] = Variable<String>(customerName);
    }
    if (!nullToAbsent || mecefStatus != null) {
      map['mecef_status'] = Variable<String>(mecefStatus);
    }
    if (!nullToAbsent || mecefQrRef != null) {
      map['mecef_qr_ref'] = Variable<String>(mecefQrRef);
    }
    return map;
  }

  SalesCompanion toCompanion(bool nullToAbsent) {
    return SalesCompanion(
      id: Value(id),
      deviceId: Value(deviceId),
      syncStatus: Value(syncStatus),
      updatedAt: Value(updatedAt),
      customerId: customerId == null && nullToAbsent
          ? const Value.absent()
          : Value(customerId),
      paymentMode: Value(paymentMode),
      subtotal: Value(subtotal),
      discount: Value(discount),
      total: Value(total),
      cashReceived: cashReceived == null && nullToAbsent
          ? const Value.absent()
          : Value(cashReceived),
      changeDue: changeDue == null && nullToAbsent
          ? const Value.absent()
          : Value(changeDue),
      status: Value(status),
      soldAt: Value(soldAt),
      customerName: customerName == null && nullToAbsent
