class SaleLine extends DataClass implements Insertable<SaleLine> {
  final String id;
  final String saleId;
  final String productId;

  /// ⚠️ Bande d'origine du sujet vendu. Renseignée par la caisse pour tout
  /// produit lié à une espèce — c'est ce qui permet d'imputer le revenu à la
  /// bande réellement vendue plutôt qu'à une répartition inventée.
  final String? lotId;
  final double qty;
  final double unitPrice;

  /// Source de vérité du montant de la ligne : le prix unitaire n'est qu'un
  /// affichage reconstitué, jamais l'inverse.
  final double manualTotalAmount;
  const SaleLine({
    required this.id,
    required this.saleId,
    required this.productId,
    this.lotId,
    required this.qty,
    required this.unitPrice,
    required this.manualTotalAmount,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<String>(id);
    map['sale_id'] = Variable<String>(saleId);
    map['product_id'] = Variable<String>(productId);
    if (!nullToAbsent || lotId != null) {
      map['lot_id'] = Variable<String>(lotId);
    }
    map['qty'] = Variable<double>(qty);
    map['unit_price'] = Variable<double>(unitPrice);
    map['manual_total_amount'] = Variable<double>(manualTotalAmount);
    return map;
  }

  SaleLinesCompanion toCompanion(bool nullToAbsent) {
    return SaleLinesCompanion(
      id: Value(id),
      saleId: Value(saleId),
      productId: Value(productId),
      lotId: lotId == null && nullToAbsent
          ? const Value.absent()
          : Value(lotId),
      qty: Value(qty),
      unitPrice: Value(unitPrice),
      manualTotalAmount: Value(manualTotalAmount),
    );
  }

  factory SaleLine.fromJson(
    Map<String, dynamic> json, {
    ValueSerializer? serializer,
  }) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return SaleLine(
      id: serializer.fromJson<String>(json['id']),
      saleId: serializer.fromJson<String>(json['saleId']),
      productId: serializer.fromJson<String>(json['productId']),
      lotId: serializer.fromJson<String?>(json['lotId']),
      qty: serializer.fromJson<double>(json['qty']),
      unitPrice: serializer.fromJson<double>(json['unitPrice']),
      manualTotalAmount: serializer.fromJson<double>(json['manualTotalAmount']),
    );
  }
  @override
  Map<String, dynamic> toJson({ValueSerializer? serializer}) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return <String, dynamic>{
      'id': serializer.toJson<String>(id),
      'saleId': serializer.toJson<String>(saleId),
      'productId': serializer.toJson<String>(productId),
      'lotId': serializer.toJson<String?>(lotId),
      'qty': serializer.toJson<double>(qty),
      'unitPrice': serializer.toJson<double>(unitPrice),
      'manualTotalAmount': serializer.toJson<double>(manualTotalAmount),
    };
  }

  SaleLine copyWith({
    String? id,
    String? saleId,
    String? productId,
    Value<String?> lotId = const Value.absent(),
    double? qty,
    double? unitPrice,
    double? manualTotalAmount,
  }) => SaleLine(
    id: id ?? this.id,
    saleId: saleId ?? this.saleId,
    productId: productId ?? this.productId,
    lotId: lotId.present ? lotId.value : this.lotId,
    qty: qty ?? this.qty,
    unitPrice: unitPrice ?? this.unitPrice,
    manualTotalAmount: manualTotalAmount ?? this.manualTotalAmount,
  );
  SaleLine copyWithCompanion(SaleLinesCompanion data) {
    return SaleLine(
      id: data.id.present ? data.id.value : this.id,
      saleId: data.saleId.present ? data.saleId.value : this.saleId,
      productId: data.productId.present ? data.productId.value : this.productId,
      lotId: data.lotId.present ? data.lotId.value : this.lotId,
      qty: data.qty.present ? data.qty.value : this.qty,
      unitPrice: data.unitPrice.present ? data.unitPrice.value : this.unitPrice,
      manualTotalAmount: data.manualTotalAmount.present
          ? data.manualTotalAmount.value
          : this.manualTotalAmount,
    );
  }

  @override
  String toString() {
    return (StringBuffer('SaleLine(')
          ..write('id: $id, ')
          ..write('saleId: $saleId, ')
          ..write('productId: $productId, ')
          ..write('lotId: $lotId, ')
          ..write('qty: $qty, ')
          ..write('unitPrice: $unitPrice, ')
          ..write('manualTotalAmount: $manualTotalAmount')
          ..write(')'))
        .toString();
  }

  @override
  int get hashCode => Object.hash(
    id,
    saleId,
    productId,
    lotId,
    qty,
    unitPrice,
    manualTotalAmount,
  );
  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      (other is SaleLine &&
          other.id == this.id &&
          other.saleId == this.saleId &&
          other.productId == this.productId &&
          other.lotId == this.lotId &&
          other.qty == this.qty &&
          other.unitPrice == this.unitPrice &&
          other.manualTotalAmount == this.manualTotalAmount);
}

