    if (!nullToAbsent || employeeName != null) {
      map['employee_name'] = Variable<String>(employeeName);
    }
    map['net_salary'] = Variable<double>(netSalary);
    map['created_at'] = Variable<DateTime>(createdAt);
    return map;
  }

