    return PayslipsCompanion(
      id: Value(id),
      employeeName: employeeName == null && nullToAbsent
          ? const Value.absent()
          : Value(employeeName),
      netSalary: Value(netSalary),
      createdAt: Value(createdAt),
    );
  }

